mapper.insert:
INSERT INTO COMMU_TAG (

    SELECT
        'CTAG'||
        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(TAG_NO), LENGTH('CTAG' ) + 1)), 0) + 1, 6, '0')
    FROM COMMU_TAG

	TAG_NO
	, BOARD_NO
	, COMMU_TAG_DATE
) VALUES (
	#{tagNo}
	, #{boardNo}
	, to_char(sysdate, 'yyyymmdd')
)

mapper.delete:
DELETE FROM COMMU_TAG 
WHERE 
	TAG_NO = #{tagNo} 
	AND 
	BOARD_NO = #{boardNo}
